+
+fn get_new_ews_ids_from_response<T, W>(response: T) -> ThinVec<nsCString>
+where
+    T: OperationResponse + Into<W>,
+    W: Into<Vec<ItemResponseMessage>>,
+{
+    response
+        .into()
+        .into()
+        .iter()
+        .filter_map(|response_message| {
+            response_message
+                .items
+                .inner
+                .first()
+                .map(|item| {
+                    item.inner_message()
+                        .item_id
+                        .as_ref()
+                        .map(|x| nsCString::from(&x.id))
+                })
+                .unwrap_or(None)
+        })
+        .collect()
+}
